@ApiOperation("账号密码重置")
    @PostMapping(value = "/account/resetPwd", produces = MediaType.APPLICATION_JSON_VALUE)
    public GenericResponse<String> accountResetPwd(@RequestBody MerchantResetPwdDTO merchantResetPwdDTO) {
        UserDTO userDTO = SecurityUtil.obtainUser();
        if (isNull(userDTO)) {
            throw new TokenException(LOGIN_EXPIRED);
        }
        return GenericResponse.success(pwdSignUtil.encrypt(merchantService.resetPwd(merchantResetPwdDTO.getAccountId(), userDTO)));
    }

public static <D> GenericResponse success(D data) {
        return new GenericResponse(null, LocalDateTime.now(), data, true);
    }

public String encrypt(String data) {
        try {
            SecretKeySpec secretKeySpec = new SecretKeySpec(pwdChangeSignKey.getBytes(), "AES");
            IvParameterSpec ivParameterSpec = new IvParameterSpec(pwdChangeSignIv.getBytes());
            Cipher cipher = Cipher.getInstance(ALGORITHM);
            cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec, ivParameterSpec);
            byte[] encrypted = cipher.doFinal(data.getBytes());
            return Base64.getEncoder().encodeToString(encrypted);
        }catch (Exception e){
            throw new RuntimeException("encrypt error", e);
        }
    }

